package cn.sifangguan.hotelaios.finance;

import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.*;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

@Service @Transactional
public class FinanceAuthorizationService {
 public record Delegation(@NotNull UUID requestId,@NotNull UUID hotelId,@NotNull @Pattern(regexp="CLAIM|OPERATION") String sourceKind,@NotNull UUID originalId,@NotNull UUID deputyId,@NotNull OffsetDateTime validFrom,@NotNull OffsetDateTime validUntil,@NotBlank @Size(max=2000)String reason){}
 public record ExceptionRequest(@NotNull UUID requestId,@NotNull UUID policyId,@NotNull @Pattern(regexp="CLAIM|OPERATION") String sourceKind,@NotNull UUID sourceId,@Min(0)int sourceVersion,@NotNull @DecimalMin("0.01")@Digits(integer=14,fraction=2)BigDecimal ceiling,@NotNull OffsetDateTime validUntil,@NotBlank @Size(max=2000)String reason){}
 public record Decision(@Min(0)int expectedVersion,boolean approved,@NotBlank @Size(max=2000)String note){}
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final EffectiveIdentityService identities;
 public FinanceAuthorizationService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,EffectiveIdentityService identities){this.jdbc=jdbc;this.database=database;this.access=access;this.identities=identities;}
 private TenantPrincipal prepare(String... permissions){access.requireAnyPermission(permissions);var p=access.principal();database.apply(p.tenantId());return p;}
 private Map<String,Object> one(TenantPrincipal p,String table,UUID id,boolean lock){var rows=jdbc.queryForList("select * from "+table+" where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));if(rows.isEmpty())throw missing();return rows.getFirst();}
 public Map<String,Object> list(){var p=prepare("finance.configure","finance.review","finance.submit");return Map.of("delegations",value(jdbc.queryForList("select * from fd_delegation where tenant_id=:tenant and (:tenantScope or hotel_id in (:scopes)) and (:config or original_id=:actor or deputy_id=:actor) order by created_at desc limit 500",base(p).addValue("payroll",p.hasPermission("*")||p.hasPermission("finance.payroll")).addValue("tax",p.hasPermission("*")||p.hasPermission("finance.tax")).addValue("config",p.hasPermission("finance.configure")||p.hasPermission("*")))),"exceptions",value(jdbc.queryForList("select * from fc_budget_exception x where tenant_id=:tenant and (x.source_kind<>'OPERATION' or exists(select 1 from fo_document d where d.tenant_id=x.tenant_id and d.id=x.source_id and (d.type<>'PAYROLL' or :payroll) and (d.type<>'TAX_TASK' or :tax))) and (:tenantScope or hotel_id in (:scopes)) and (:config or applicant_id=:actor or reviewer_id=:actor) order by created_at desc limit 500",base(p).addValue("payroll",p.hasPermission("*")||p.hasPermission("finance.payroll")).addValue("tax",p.hasPermission("*")||p.hasPermission("finance.tax")).addValue("config",p.hasPermission("finance.configure")||p.hasPermission("*")))));}
 public Map<String,Object> createDelegation(Delegation in){var p=prepare("finance.configure");access.requireOrgScope(in.hotelId());if(in.originalId().equals(in.deputyId())||!in.validUntil().isAfter(in.validFrom())||Duration.between(in.validFrom(),in.validUntil()).compareTo(Duration.ofDays(90))>0||in.validUntil().isBefore(OffsetDateTime.now()))throw bad("代理必须是不同实际人员、有效窗口最长90日，不能回溯授权已发生审批");requireReviewerIdentity(p,in.hotelId(),in.deputyId());
  var old=jdbc.queryForList("select * from fd_delegation where tenant_id=:tenant and id=:id",base(p).addValue("id",in.requestId()));if(!old.isEmpty()){var r=old.getFirst();if(!in.hotelId().equals(r.get("hotel_id"))||!in.sourceKind().equals(r.get("source_kind"))||!p.actorId().equals(r.get("created_by"))||!in.originalId().equals(r.get("original_id"))||!in.deputyId().equals(r.get("deputy_id"))||!in.reason().equals(r.get("reason"))||!in.validFrom().toInstant().equals(instant(r.get("valid_from")))||!in.validUntil().toInstant().equals(instant(r.get("valid_until"))))throw conflict("授权编号已用于不同内容");return output(r);}
  jdbc.update("insert into fd_delegation(id,tenant_id,hotel_id,source_kind,original_id,deputy_id,valid_from,valid_until,reason,created_by) values(:id,:tenant,:hotel,:kind,:original,:deputy,:from,:until,:reason,:actor)",base(p).addValue("id",in.requestId()).addValue("hotel",in.hotelId()).addValue("kind",in.sourceKind()).addValue("original",in.originalId()).addValue("deputy",in.deputyId()).addValue("from",in.validFrom()).addValue("until",in.validUntil()).addValue("reason",in.reason()));return output(one(p,"fd_delegation",in.requestId(),false));}
 public Map<String,Object> publishDelegation(UUID id,Decision in,boolean revoke){var p=prepare("finance.configure");var r=one(p,"fd_delegation",id,true);access.requireOrgScope(id(r.get("hotel_id")));version(r,in.expectedVersion());if(revoke){if(!"PUBLISHED".equals(r.get("status")))throw conflict("只能撤销已发布代理");}else{if(!"DRAFT".equals(r.get("status"))||p.actorId().equals(r.get("created_by"))||p.actorId().equals(r.get("deputy_id")))throw conflict("代理授权需另一名非代理本人的配置人员独立发布");requireReviewerIdentity(p,id(r.get("hotel_id")),id(r.get("deputy_id")));jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,100))",Map.of("key",p.tenantId()+":deputy:"+r.get("hotel_id")+":"+r.get("source_kind")+":"+r.get("original_id")),Object.class);if(jdbc.queryForObject("select count(*) from fd_delegation where tenant_id=:tenant and hotel_id=:hotel and source_kind=:kind and original_id=:original and status='PUBLISHED' and valid_from<:until and valid_until>:from",base(p).addValue("hotel",r.get("hotel_id")).addValue("kind",r.get("source_kind")).addValue("original",r.get("original_id")).addValue("from",r.get("valid_from")).addValue("until",r.get("valid_until")),Integer.class)>0)throw conflict("该原审核人的代理有效窗口重叠");}
  jdbc.update("update fd_delegation set status=:status,published_by=coalesce(published_by,:actor),version=version+1 where tenant_id=:tenant and id=:id",base(p).addValue("id",id).addValue("status",revoke?"REVOKED":in.approved()?"PUBLISHED":"REJECTED"));new FinanceControlGuard(jdbc).event(p,id(r.get("hotel_id")),"DELEGATION",id,revoke?"REVOKED":"REVIEWED",Map.of("authorization",output(r),"note",in.note()));return output(one(p,"fd_delegation",id,false));}
 private void requireReviewerIdentity(TenantPrincipal p,UUID hotel,UUID account){var choices=jdbc.queryForList("select a.id from employee_position_assignment a join employee e on e.tenant_id=a.tenant_id and e.id=a.employee_id where a.tenant_id=:tenant and e.account_id=:user and a.status='ACTIVE' and e.employment_status='ACTIVE' and a.valid_from<=current_date and (a.valid_to is null or a.valid_to>=current_date)",base(p).addValue("user",account));var ids=new ArrayList<UUID>();ids.add(null);choices.forEach(r->ids.add(id(r.get("id"))));for(UUID assignment:ids){var identity=identities.inspectNotificationRecipient(p.tenantId(),account,assignment);if(identity.isPresent()){var candidate=identity.get();if((candidate.hasPermission("finance.review")||candidate.hasPermission("*"))&&(candidate.hasTenantScope()||candidate.orgScopes().contains(hotel)))return;}}throw conflict("代理人当前没有该组织财务审核权限或有效任职；授权不会自动授予权限");}
 public Map<String,Object> requestException(ExceptionRequest in){var p=prepare("finance.submit","finance.configure");String table=in.sourceKind().equals("CLAIM")?"finance_claim":"fo_document";var source=one(p,table,in.sourceId(),true);if("PAYROLL".equals(source.get("type")))access.requirePermission("finance.payroll");if("TAX_TASK".equals(source.get("type")))access.requirePermission("finance.tax");UUID hotel=id(source.get("hotel_id"));access.requireOrgScope(hotel);version(source,in.sourceVersion());if(!Set.of("DRAFT","RETURNED").contains(source.get("status"))||!p.actorId().equals(source.get("applicant_id")))throw conflict("只能为本人当前未提交草稿申请预算例外");var policy=one(p,"fc_policy",in.policyId(),false);if(!hotel.equals(policy.get("hotel_id"))||!"BUDGET".equals(policy.get("kind"))||!"PUBLISHED".equals(policy.get("status")))throw bad("须选择本组织已发布预算版本");if(in.validUntil().isBefore(OffsetDateTime.now())||in.validUntil().isAfter(OffsetDateTime.now().plusDays(30)))throw bad("例外须在未来30日内有效，不能无限期授权");var config=jdbc.queryForMap("select * from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and enabled",base(p).addValue("hotel",hotel));UUID reviewer=id(config.get("director_account_id"));if(reviewer==null||reviewer.equals(p.actorId()))throw conflict("请配置独立财务总监处理预算例外");
  var b=base(p).addValue("id",in.requestId());var old=jdbc.queryForList("select * from fc_budget_exception where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){var r=old.getFirst();if(!in.sourceId().equals(r.get("source_id"))||in.sourceVersion()!=((Number)r.get("source_version")).intValue()||!in.policyId().equals(r.get("policy_id"))||in.ceiling().compareTo(amount(r.get("ceiling")))!=0||!in.reason().equals(r.get("reason")))throw conflict("例外编号已用于不同内容");return output(r);}
  jdbc.update("insert into fc_budget_exception(id,tenant_id,hotel_id,policy_id,source_kind,source_id,source_version,ceiling,valid_until,reason,applicant_id,reviewer_id) values(:id,:tenant,:hotel,:policy,:kind,:source,:version,:ceiling,:until,:reason,:actor,:reviewer)",b.addValue("hotel",hotel).addValue("policy",in.policyId()).addValue("kind",in.sourceKind()).addValue("source",in.sourceId()).addValue("version",in.sourceVersion()).addValue("ceiling",in.ceiling()).addValue("until",in.validUntil()).addValue("reason",in.reason()).addValue("reviewer",reviewer));return output(one(p,"fc_budget_exception",in.requestId(),false));}
 public Map<String,Object> reviewException(UUID id,Decision in){var p=prepare("finance.review");var first=one(p,"fc_budget_exception",id,false);var source=one(p,first.get("source_kind").equals("CLAIM")?"finance_claim":"fo_document",id(first.get("source_id")),true);if("PAYROLL".equals(source.get("type")))access.requirePermission("finance.payroll");if("TAX_TASK".equals(source.get("type")))access.requirePermission("finance.tax");var r=one(p,"fc_budget_exception",id,true);access.requireOrgScope(id(r.get("hotel_id")));version(r,in.expectedVersion());if(!"REVIEW".equals(r.get("status"))||!p.actorId().equals(r.get("reviewer_id"))||p.actorId().equals(r.get("applicant_id")))throw conflict("须配置总监独立处理当前预算例外");if(in.approved()&&!instant(r.get("valid_until")).isAfter(Instant.now()))throw conflict("预算例外已过有效期，请重新申请");if(in.approved()&&(((Number)source.get("version")).intValue()!=((Number)r.get("source_version")).intValue()||!Set.of("DRAFT","RETURNED").contains(source.get("status"))))throw conflict("来源草稿已改变，请重新申请，不将旧例外挪用到新内容");jdbc.update("update fc_budget_exception set status=:status,reviewed_by=:actor,review_note=:note,version=version+1 where tenant_id=:tenant and id=:id",base(p).addValue("id",id).addValue("status",in.approved()?"APPROVED":"REJECTED").addValue("note",in.note()));new FinanceControlGuard(jdbc).event(p,id(r.get("hotel_id")),r.get("source_kind").toString(),id(r.get("source_id")),"BUDGET_EXCEPTION_REVIEWED",Map.of("exception",output(r),"approved",in.approved(),"note",in.note()));return output(one(p,"fc_budget_exception",id,false));}
 private static Instant instant(Object value){if(value instanceof OffsetDateTime date)return date.toInstant();if(value instanceof java.util.Date date)return date.toInstant();return Instant.parse(value.toString());}
}
